package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import it.cavallium.rockserver.core.common.export.ExportJobs;
import java.io.*;
import java.nio.channels.*;
import java.nio.file.*;
import java.util.*;

/** Parent-owned frozen input, issued slots and complete capture vector. Child journals alone own chunk ACKs. */
public final class RatisAggregateExportJournal implements RatisDatabaseCaptureCoordinator.Log,AutoCloseable {
    public record Slot(UUID domainId,SnapshotFence fence,SessionEpochLedger issuance,Path snapshot,UUID childJob){
        public Slot{Objects.requireNonNull(domainId);Objects.requireNonNull(fence);Objects.requireNonNull(issuance);Objects.requireNonNull(snapshot);Objects.requireNonNull(childJob);if(!domainId.equals(fence.domainId()) || issuance.grants().isEmpty() || !snapshot.isAbsolute() || !snapshot.normalize().equals(snapshot) || snapshot.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>4096)throw new IllegalArgumentException("Invalid aggregate issued slot");var grant=issuance.grants().getLast();var business=fence.operation();var first=fence.participants().stream().map(SnapshotFence.Participant::installOperation).min(Comparator.comparingLong(OperationId::sequence)).orElseThrow();if(!issuance.clusterId().equals(fence.clusterId()) || !issuance.databaseId().equals(fence.databaseId()) || !grant.sessionId().equals(business.sessionId()) || grant.epoch()!=business.epoch() || !first.sessionId().equals(business.sessionId()) || first.epoch()!=business.epoch() || first.sequence()!=business.sequence()+1 || first.sequence()>4096-RatisSnapshotClient.CONTROL_SLOTS)throw new IllegalArgumentException("Aggregate slot is outside original issued512 control block");}
        public RatisGrantIssuer.Issued issued(){return new RatisGrantIssuer.Issued(issuance,issuance.grants().getLast());}
    }
    private final RatisJournalAccess journalAccess;
    RatisJournalAccess journalAccess(){return journalAccess;}
    private final Path path;private final DatabaseExportDefinition input;private final FileChannel channel;private final FileLock lock;
    private final Map<UUID,byte[]> sourceIdentities=new LinkedHashMap<>();private List<Slot> slots=List.of();private DatabaseBackupDefinition barrier;private DatabaseExportCaptures captureWitness;private RatisDatabaseBackupJournal.Snapshot capture;
    private ExportJobs.Phase phase=ExportJobs.Phase.CAPTURING;private boolean drained,published,closed,fenced;
    public static RatisAggregateExportJournal create(Path path,DatabaseExportDefinition input)throws IOException{return new RatisAggregateExportJournal(path,input,false,RatisJournalAccess.standalone());}
    public static RatisAggregateExportJournal reopen(Path path)throws IOException{return new RatisAggregateExportJournal(path,null,true,RatisJournalAccess.standalone());}
    static RatisAggregateExportJournal createOwned(Path path,DatabaseExportDefinition input,RatisJournalAccess access)throws IOException{return new RatisAggregateExportJournal(path,input,false,access);}
    static RatisAggregateExportJournal reopenOwned(Path path,RatisJournalAccess access)throws IOException{return new RatisAggregateExportJournal(path,null,true,access);}
    private RatisAggregateExportJournal(Path path,DatabaseExportDefinition proposed,boolean reopen,RatisJournalAccess access)throws IOException{
        journalAccess=Objects.requireNonNull(access);access.register(path,DatabaseExportDefinition.MAX_BYTES);access.register(path.resolveSibling(path.getFileName()+".lock"),32);
        this.path=path.toAbsolutePath().normalize();if(!Files.isDirectory(this.path.getParent(),LinkOption.NOFOLLOW_LINKS))throw new IOException("Aggregate parent directory absent");channel=FileChannel.open(this.path.resolveSibling(this.path.getFileName()+".lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS);FileLock acquired=null;
        try{acquired=channel.tryLock();if(acquired==null)throw new IOException("Aggregate export already owned");lock=acquired;if(reopen){var body=journalAccess.read(this.path,DatabaseExportDefinition.MAX_BYTES);var in=new DataInputStream(new ByteArrayInputStream(body));if(in.readInt()!=0x4145584a)throw new IOException("Invalid aggregate journal");input=DatabaseExportDefinition.decode(blob(in,DatabaseExportDefinition.MAX_BYTES));decodeState(in);if(in.available()!=0 || !Arrays.equals(body,encode()))throw new IOException("Noncanonical aggregate journal");SessionJournalFiles.force(this.path);SessionJournalFiles.force(this.path.getParent());}else{input=Objects.requireNonNull(proposed);if(Files.exists(this.path,LinkOption.NOFOLLOW_LINKS) || Files.exists(this.path.resolveSibling(this.path.getFileName()+".pending"),LinkOption.NOFOLLOW_LINKS))throw new IOException("Aggregate export attempt already exists");save();}}
        catch(Throwable failure){if(acquired!=null)acquired.close();channel.close();throw failure;}
    }
    public DatabaseExportDefinition input(){return input;}public synchronized boolean hasBarrier(){return barrier!=null;}public Path path(){return path;}public synchronized List<Slot> slots()throws IOException{open();return slots;}public synchronized ExportJobs.Phase phase()throws IOException{open();return phase;}public synchronized boolean drained()throws IOException{open();return drained;}public synchronized boolean readyPublished()throws IOException{open();return published;}
    public synchronized void allocated(Slot slot)throws IOException{open();if(barrier!=null || phase!=ExportJobs.Phase.CAPTURING)throw new IOException("Aggregate capture allocation closed");var domain=input.domain(slot.domainId());domain.schema().requireMatches(domain.directory());if(!Arrays.equals(slot.fence().schemaDigest(),domain.schema().digest()) || slot.fence().directoryGeneration()!=domain.directory().generation())throw new IOException("Allocated fence changed original vector");if(slots.stream().anyMatch(old->old.fence().fenceId().equals(slot.fence().fenceId()) || old.childJob().equals(slot.childJob()) || old.snapshot().equals(slot.snapshot())))throw new IOException("Repeated issued aggregate slot");var next=new ArrayList<>(slots);next.add(slot);slots=List.copyOf(next);save();}
    public synchronized void sourceBound(Slot slot,byte[] identity)throws IOException{open();if(identity.length!=32 || !slots.contains(slot))throw new IOException("Source identity lacks original issued slot");var prior=sourceIdentities.get(slot.fence().fenceId());if(prior!=null){if(!Arrays.equals(prior,identity))throw new IOException("Original aggregate source identity changed");return;}sourceIdentities.put(slot.fence().fenceId(),identity.clone());save();}
    public synchronized boolean hasSourceIdentity(Slot slot)throws IOException{open();if(!slots.contains(slot))throw new IOException("Source identity lacks original issued slot");return sourceIdentities.containsKey(slot.fence().fenceId());}
    public synchronized byte[] sourceIdentity(Slot slot)throws IOException{open();var identity=sourceIdentities.get(slot.fence().fenceId());if(identity==null)throw new IOException("Original aggregate source identity absent");return identity.clone();}
    public synchronized void allocatedComplete(DatabaseBackupDefinition definition)throws IOException{open();if(barrier!=null){if(!Arrays.equals(barrier.encode(),definition.encode()))throw new IOException("Aggregate barrier changed");return;}if(!definition.backupId().equals(input.jobId()) || !Arrays.equals(definition.roster().encode(),input.roster().encode()))throw new IOException("Aggregate barrier identity changed");var fences=slots.stream().map(Slot::fence).collect(java.util.stream.Collectors.toSet());var expected=definition.domains().stream().flatMap(domain->domain.fences().stream()).collect(java.util.stream.Collectors.toSet());if(!fences.equals(expected))throw new IOException("Aggregate issued slot coverage changed");barrier=definition;capture=new RatisDatabaseBackupJournal.Snapshot(RatisDatabaseBackupJournal.Phase.GATES,List.of(),List.of(),List.of(),List.of(),0);save();}
    @Override public DatabaseBackupDefinition definition(){if(barrier==null)throw new IllegalStateException("Aggregate slots not yet frozen");return barrier;}
    @Override public RatisDatabaseBackupDriver.Policy policy(){return new RatisDatabaseBackupDriver.Policy(input.limits().snapshotTtl(),input.limits().snapshotTtl(),1024);}
    @Override public synchronized RatisDatabaseBackupJournal.Snapshot snapshot()throws IOException{open();if(capture==null)throw new IOException("Aggregate slots not yet frozen");return capture;}
    @Override public synchronized void freezeRequests(List<RatisDatabaseBackupJournal.CohortRequest> requests)throws IOException{open();if(capture.phase()!=RatisDatabaseBackupJournal.Phase.GATES)throw new IOException("Aggregate requests already frozen");if(requests.size()>policy().maximumCohorts())throw new IOException("Aggregate cohort count exhausted");capture=new RatisDatabaseBackupJournal.Snapshot(RatisDatabaseBackupJournal.Phase.REQUESTS,requests,List.of(),List.of(),List.of(),System.currentTimeMillis());save();}
    @Override public synchronized void captured(List<SnapshotFenceStatus> statuses)throws IOException{open();if(capture.phase()!=RatisDatabaseBackupJournal.Phase.REQUESTS)throw new IOException("Aggregate capture vector not accepting results");var proposed=new RatisDatabaseBackupJournal.Snapshot(RatisDatabaseBackupJournal.Phase.CAPTURED,capture.requests(),statuses,List.of(),List.of(),capture.dispatchStartedMillis());var proof=witness(proposed);capture=proposed;save();captureWitness=proof;}
    @Override public synchronized void phase(RatisDatabaseBackupJournal.Phase next)throws IOException{open();if(capture.phase()==next)return;boolean valid=capture.phase()==RatisDatabaseBackupJournal.Phase.CAPTURED&&next==RatisDatabaseBackupJournal.Phase.REPORTED || capture.phase()==RatisDatabaseBackupJournal.Phase.REPORTED&&next==RatisDatabaseBackupJournal.Phase.RELEASED;if(!valid && next!=RatisDatabaseBackupJournal.Phase.LOST && next!=RatisDatabaseBackupJournal.Phase.CANCELLED)throw new IOException("Invalid aggregate capture phase");capture=new RatisDatabaseBackupJournal.Snapshot(next,capture.requests(),capture.captured(),List.of(),List.of(),capture.dispatchStartedMillis());if(next==RatisDatabaseBackupJournal.Phase.RELEASED)phase=ExportJobs.Phase.EXPORTING;else if(next==RatisDatabaseBackupJournal.Phase.LOST)phase=ExportJobs.Phase.SNAPSHOT_LOST;else if(next==RatisDatabaseBackupJournal.Phase.CANCELLED)phase=ExportJobs.Phase.CANCELLED;save();}
    public synchronized void materialized()throws IOException{open();if(phase!=ExportJobs.Phase.EXPORTING&&phase!=ExportJobs.Phase.MATERIALIZED)throw new IOException("Aggregate children not exporting");phase=ExportJobs.Phase.MATERIALIZED;save();}
    public synchronized void graphDrained()throws IOException{open();if(phase!=ExportJobs.Phase.MATERIALIZED&&phase!=ExportJobs.Phase.CANCELLED&&phase!=ExportJobs.Phase.SNAPSHOT_LOST)throw new IOException("Aggregate graph cannot drain yet");drained=true;save();}
    public synchronized void ready()throws IOException{open();if(phase!=ExportJobs.Phase.MATERIALIZED || !drained)throw new IOException("Aggregate READY requires materialization and actual graph drain");phase=ExportJobs.Phase.READY;published=true;save();}
    public synchronized void terminal(ExportJobs.Phase next)throws IOException{open();if(next!=ExportJobs.Phase.CANCELLED && next!=ExportJobs.Phase.SNAPSHOT_LOST && next!=ExportJobs.Phase.RELEASED)throw new IOException("Invalid aggregate terminal");if(phase==ExportJobs.Phase.RELEASED)return;if(next==ExportJobs.Phase.RELEASED && phase!=ExportJobs.Phase.READY && phase!=ExportJobs.Phase.CANCELLED && phase!=ExportJobs.Phase.SNAPSHOT_LOST)throw new IOException("Aggregate release not qualified");phase=next;save();}
    public synchronized DatabaseExportCaptures captures()throws IOException{open();if(capture==null||capture.captured().isEmpty())return null;if(captureWitness==null)captureWitness=witness(capture);return captureWitness;}
    public synchronized byte[] captureBytes()throws IOException{open();var value=captures();return value==null?new byte[0]:value.encode();}
    private DatabaseExportCaptures witness(RatisDatabaseBackupJournal.Snapshot value){return new DatabaseExportCaptures(input,barrier,value.captured(),value.requests().stream().map(request->new DatabaseExportCaptures.Cohort(request.cohortId(),request.nodeIncarnation(),request.processIncarnation(),request.poolId(),request.members().stream().map(RatisDatabaseBackupJournal.Member::groupId).toList())).toList());}
    private void open()throws IOException{if(closed||fenced)throw new IOException("Aggregate journal closed/fenced; reopen original owner");}
    private void save()throws IOException{try{journalAccess.write(path,encode(),(int)input.limits().maximumJournalBytes());}catch(IOException|RuntimeException failed){fenced=true;throw failed;}}
    private byte[] encode()throws IOException{return bounded((int)input.limits().maximumJournalBytes()-32,out->{out.writeInt(0x4145584a);blob(out,input.encode());out.writeByte(phase.ordinal());out.writeBoolean(drained);out.writeBoolean(published);out.writeInt(slots.size());for(var slot:slots){uuid(out,slot.domainId());blob(out,slot.fence().encode());blob(out,slot.issuance().encode());out.writeUTF(slot.snapshot().toString());uuid(out,slot.childJob());}out.writeInt(sourceIdentities.size());for(var entry:sourceIdentities.entrySet()){uuid(out,entry.getKey());out.write(entry.getValue());}out.writeBoolean(barrier!=null);if(barrier!=null){blob(out,barrier.encode());out.writeByte(capture.phase().ordinal());out.writeLong(capture.dispatchStartedMillis());out.writeInt(capture.requests().size());for(var request:capture.requests()){uuid(out,request.cohortId());uuid(out,request.nodeIncarnation());uuid(out,request.processIncarnation());uuid(out,request.poolId());out.writeInt(request.members().size());for(var member:request.members()){uuid(out,member.fenceId());uuid(out,member.groupId());uuid(out,member.snapshotId());uuid(out,member.owner());uuid(out,member.replica());out.writeLong(member.ttlMillis());out.write(member.preparedDigest());}}out.writeInt(capture.captured().size());for(var status:capture.captured())blob(out,status.encode());}});}
    private void decodeState(DataInputStream in)throws IOException{int p=in.readUnsignedByte();if(p>=ExportJobs.Phase.values().length)throw new IOException("Invalid aggregate phase");phase=ExportJobs.Phase.values()[p];drained=in.readBoolean();published=in.readBoolean();int count=count(in,DatabaseBackupDefinition.MAX_RANGES);var restored=new ArrayList<Slot>();for(int n=0;n<count;n++)restored.add(new Slot(uuid(in),SnapshotFence.decode(blob(in,SnapshotFence.MAX_BYTES)),SessionEpochLedger.decode(blob(in,SessionEpochLedger.MAX_BYTES)),Path.of(in.readUTF()),uuid(in)));slots=List.copyOf(restored);count=count(in,DatabaseBackupDefinition.MAX_RANGES);for(int n=0;n<count;n++){UUID id=uuid(in);byte[] identity=in.readNBytes(32);if(identity.length!=32 || sourceIdentities.putIfAbsent(id,identity)!=null || slots.stream().noneMatch(slot->slot.fence().fenceId().equals(id)))throw new IOException("Invalid frozen aggregate source identity");}if(in.readBoolean()){barrier=DatabaseBackupDefinition.decode(blob(in,DatabaseBackupDefinition.MAX_BYTES));int c=in.readUnsignedByte();if(c>=RatisDatabaseBackupJournal.Phase.values().length)throw new IOException("Invalid aggregate capture phase");long started=in.readLong();count=count(in,1024);var requests=new ArrayList<RatisDatabaseBackupJournal.CohortRequest>();for(int n=0;n<count;n++){UUID id=uuid(in),node=uuid(in),process=uuid(in),pool=uuid(in);int members=count(in,1024);var list=new ArrayList<RatisDatabaseBackupJournal.Member>();for(int m=0;m<members;m++)list.add(new RatisDatabaseBackupJournal.Member(uuid(in),uuid(in),uuid(in),uuid(in),uuid(in),in.readLong(),in.readNBytes(32)));requests.add(new RatisDatabaseBackupJournal.CohortRequest(id,node,process,pool,list));}count=count(in,DatabaseBackupDefinition.MAX_RANGES);var statuses=new ArrayList<SnapshotFenceStatus>();for(int n=0;n<count;n++)statuses.add(SnapshotFenceStatus.decode(blob(in,SnapshotFenceStatus.MAX_BYTES)));capture=new RatisDatabaseBackupJournal.Snapshot(RatisDatabaseBackupJournal.Phase.values()[c],requests,statuses,List.of(),List.of(),started);if(!statuses.isEmpty())captureWitness=witness(capture);}}
    @Override public synchronized void close()throws IOException{if(closed)return;closed=true;try{lock.close();}finally{channel.close();}}
    @FunctionalInterface private interface Write{void write(DataOutputStream out)throws IOException;}
    private static byte[] bounded(int max,Write write)throws IOException{var buffer=new ByteArrayOutputStream();var stream=new OutputStream(){int size;void reserve(int n)throws IOException{if(n>max-size)throw new IOException("Aggregate journal byte budget exhausted before growth");size+=n;}public void write(int value)throws IOException{reserve(1);buffer.write(value);}public void write(byte[] bytes,int offset,int length)throws IOException{reserve(length);buffer.write(bytes,offset,length);}};write.write(new DataOutputStream(stream));return buffer.toByteArray();}
    private static void uuid(DataOutputStream out,UUID id)throws IOException{out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());}private static UUID uuid(DataInputStream in)throws IOException{return new UUID(in.readLong(),in.readLong());}
    private static void blob(DataOutputStream out,byte[] bytes)throws IOException{out.writeInt(bytes.length);out.write(bytes);}private static byte[] blob(DataInputStream in,int max)throws IOException{int n=in.readInt();if(n<0||n>max||n>in.available())throw new IOException("Invalid aggregate blob");return in.readNBytes(n);}private static int count(DataInputStream in,int max)throws IOException{int n=in.readInt();if(n<0||n>max||n>in.available())throw new IOException("Invalid aggregate count");return n;}
}
